import{_ as e,o as n,c as d,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"09 — Quản trị Hệ thống Nền tảng (Admin Functions)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/09-admin-management.md","filePath":"ba/09-admin-management.md"}'),c={name:"ba/09-admin-management.md"};function i(g,t,a,l,h,r){return n(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="_09-—-quan-tri-he-thong-nen-tang-admin-functions" tabindex="-1">09 — Quản trị Hệ thống Nền tảng (Admin Functions) <a class="header-anchor" href="#_09-—-quan-tri-he-thong-nen-tang-admin-functions" aria-label="Permalink to &quot;09 — Quản trị Hệ thống Nền tảng (Admin Functions)&quot;">​</a></h1><p>&gt; [&lt;&lt; 08 - Subscription &amp; Billing](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/08-subscription-billing.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 10 - Roles &amp; Permissions Matrix &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/10-roles-permissions-matrix.md) &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.10 Admin Functions</code> — 14 FR (<code>3.10.1</code> – <code>3.10.14</code>)</strong> | <code>UC-128</code> – <code>UC-141</code> (cùng <code>3.7.13 Crawl Schedule Config</code> thuộc quyền <code>Admin</code>). &gt; Toàn bộ 14 chức năng trong miền này chỉ dành riêng cho vai trò chuẩn <strong><code>Admin</code></strong> (<code>ADMIN</code>).</p><hr><h2 id="_1-bang-tong-hop-14-yeu-cau-chuc-nang-chuan-3-10-1-–-3-10-14" tabindex="-1">1. Bảng Tổng hợp 14 Yêu cầu Chức năng Chuẩn (<code>3.10.1</code> – <code>3.10.14</code>) <a class="header-anchor" href="#_1-bang-tong-hop-14-yeu-cau-chuc-nang-chuan-3-10-1-–-3-10-14" aria-label="Permalink to &quot;1. Bảng Tổng hợp 14 Yêu cầu Chức năng Chuẩn (`3.10.1` – `3.10.14`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.10.1</code></strong></td><td style="text-align:center;"><code>UC-128</code></td><td style="text-align:left;"><strong>View User List</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem danh sách toàn bộ tài khoản người dùng trên nền tảng (tìm kiếm theo tên/email, lọc theo trạng thái hoạt động, vai trò, mức độ vi phạm và phân trang chuẩn).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.2</code></strong></td><td style="text-align:center;"><code>UC-129</code></td><td style="text-align:left;"><strong>View User Detail</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem hồ sơ chi tiết của một người dùng, danh sách các <code>Agency</code>/<code>Workspace</code> họ tham gia, lịch sử hoạt động và lịch sử vi phạm (hỗ trợ mở bằng 3 chế độ <code>Side Peek</code>, <code>Center Modal</code>, <code>Full Page</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.3</code></strong></td><td style="text-align:center;"><code>UC-130</code></td><td style="text-align:left;"><strong>Update User Status</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Khóa (<code>BAN</code> / <code>LOCK</code>) hoặc mở khóa (<code>ACTIVATE</code>) tài khoản người dùng; khi bị khóa, thu hồi ngay lập tức các phiên đăng nhập JWT đang hoạt động của tài khoản đó.</td></tr><tr><td style="text-align:center;"><strong><code>3.10.4</code></strong></td><td style="text-align:center;"><code>UC-131</code></td><td style="text-align:left;"><strong>Content Moderation Queue</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem và xử lý Hàng đợi Kiểm duyệt Nội dung (<code>Content Moderation Queue</code>): duyệt cho phép (<code>APPROVE</code>), gỡ bỏ/từ chối (<code>REJECT</code>) các bài viết/bình luận bị hệ thống AI gắn cờ vi phạm tiêu chuẩn cộng đồng.</td></tr><tr><td style="text-align:center;"><strong><code>3.10.5</code></strong></td><td style="text-align:center;"><code>UC-132</code></td><td style="text-align:left;"><strong>Update User Violation Status</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Cập nhật mức độ cảnh cáo / điểm vi phạm (<code>violationStatus</code> / <code>strikeCount</code>) của người dùng sau khi xác minh nội dung vi phạm tại hàng đợi kiểm duyệt.</td></tr><tr><td style="text-align:center;"><strong><code>3.10.6</code></strong></td><td style="text-align:center;"><code>UC-133</code></td><td style="text-align:left;"><strong>View Subscription Plan List</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem danh sách cấu hình các gói cước dịch vụ (<code>Basic</code>, <code>Plus</code>/<code>Pro</code>, <code>Enterprise</code>) trên toàn hệ thống cùng số lượng thuê bao đang đăng ký mỗi gói.</td></tr><tr><td style="text-align:center;"><strong><code>3.10.7</code></strong></td><td style="text-align:center;"><code>UC-134</code></td><td style="text-align:left;"><strong>Create Subscription Plan</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Tạo mới một gói cước dịch vụ (Mã gói, Tên hiển thị <code>vi</code>/<code>en</code>, Giá tiền VND, Chu kỳ tháng/năm, Định mức AI Credit cấp định kỳ, Định mức gửi Email Newsletter và danh sách tính năng).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.8</code></strong></td><td style="text-align:center;"><code>UC-135</code></td><td style="text-align:left;"><strong>Update Subscription Plan</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Cập nhật đơn giá, định mức quyền lợi hoặc mô tả của gói cước (áp dụng cho các đơn đăng ký/gia hạn mới; bảo toàn quyền lợi đã chốt của chu kỳ đang chạy).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.9</code></strong></td><td style="text-align:center;"><code>UC-136</code></td><td style="text-align:left;"><strong>Delete Subscription Plan</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xóa hoặc ngừng cung cấp (<code>Archive</code>/<code>Deactivate</code>) một gói cước khi không còn thuê bao đang hoạt động trên gói đó.</td></tr><tr><td style="text-align:center;"><strong><code>3.10.10</code></strong></td><td style="text-align:center;"><code>UC-137</code></td><td style="text-align:left;"><strong>View AI Credit Price List</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem bảng giá AI Credit hiện hành cho các nhóm tác vụ AI tính phí (<code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, <code>VIDEO_GENERATE</code>) cùng lịch sử phiên bản giá (<code>rate_version</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.11</code></strong></td><td style="text-align:center;"><code>UC-138</code></td><td style="text-align:left;"><strong>Update AI Credit Price</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Cập nhật số lượng AI Credit tiêu tốn (<code>unit_credits</code>) hoặc bật/tắt trạng thái kích hoạt của từng tác vụ AI; tự động tạo bản chụp phiên bản giá mới để không ảnh hưởng các giao dịch đang tạm giữ (<code>HOLD</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.12</code></strong></td><td style="text-align:center;"><code>UC-139</code></td><td style="text-align:left;"><strong>Import AI Credit Price CSV</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Nhập hàng loạt bảng cấu hình giá AI Credit từ tệp CSV chuẩn (kiểm tra định dạng cột, mã tác vụ hợp lệ, số credit nguyên không âm và áp dụng nguyên tử).</td></tr><tr><td style="text-align:center;"><strong><code>3.10.13</code></strong></td><td style="text-align:center;"><code>UC-140</code></td><td style="text-align:left;"><strong>View Revenue Dashboard</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xem Bảng điều khiển Doanh thu &amp; Tài chính toàn hệ thống: tổng doanh thu SePay theo khoảng thời gian, cơ cấu doanh thu theo gói cước, thống kê hóa đơn (<code>PAID</code>, <code>PENDING</code>, <code>EXPIRED</code>) và lượng tiêu thụ AI Credit.</td></tr><tr><td style="text-align:center;"><strong><code>3.10.14</code></strong></td><td style="text-align:center;"><code>UC-141</code></td><td style="text-align:left;"><strong>Export Report File PDF</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:left;">Xuất báo cáo tổng hợp doanh thu, hóa đơn và vận hành hệ thống ra tệp <strong>PDF</strong> chính thức để lưu trữ và đối soát kế toán.</td></tr></tbody></table><hr><h2 id="_2-đac-ta-nghiep-vu-chi-tiet-cac-phan-he-quan-tri-admin-portal" tabindex="-1">2. Đặc tả Nghiệp vụ Chi tiết Các Phân hệ Quản trị (<code>Admin Portal</code>) <a class="header-anchor" href="#_2-đac-ta-nghiep-vu-chi-tiet-cac-phan-he-quan-tri-admin-portal" aria-label="Permalink to &quot;2. Đặc tả Nghiệp vụ Chi tiết Các Phân hệ Quản trị (`Admin Portal`)&quot;">​</a></h2><h3 id="_2-1-quan-tri-nguoi-dung-kiem-duyet-an-toan-noi-dung-3-10-1-–-3-10-5" tabindex="-1">2.1. Quản trị Người dùng &amp; Kiểm duyệt An toàn Nội dung (<code>3.10.1</code> – <code>3.10.5</code>) <a class="header-anchor" href="#_2-1-quan-tri-nguoi-dung-kiem-duyet-an-toan-noi-dung-3-10-1-–-3-10-5" aria-label="Permalink to &quot;2.1. Quản trị Người dùng &amp; Kiểm duyệt An toàn Nội dung (`3.10.1` – `3.10.5`)&quot;">​</a></h3><ol><li><strong>Quản lý Tài khoản (<code>3.10.1</code>, <code>3.10.2</code>, <code>3.10.3</code>)</strong>: <ul><li>Tại <code>/admin/users</code>, <code>Admin</code> tra cứu người dùng, mở xem chi tiết (<code>3.10.2</code>) bằng 1 trong 3 chế độ <strong>Notion Peek (<code>Side Peek</code>, <code>Center Modal</code>, <code>Full Page</code>)</strong>.</li><li><code>Admin</code> không thể tự khóa (<code>BAN</code>) chính tài khoản <code>Admin</code> đang đăng nhập của mình.</li><li>Khi một tài khoản bị chuyển sang trạng thái khóa (<code>3.10.3</code>), hệ thống bắt buộc ghi nhận lý do khóa, hủy hiệu lực <code>refreshToken</code> trên Redis và chặn mọi API request tiếp theo của tài khoản đó.</li></ul></li><li><strong>Hàng đợi Kiểm duyệt Nội dung &amp; Xử lý Vi phạm (<code>3.10.4</code> &amp; <code>3.10.5</code>)</strong>: <ul><li>Khi người dùng tạo bài viết/caption (<code>3.6.33 Check Compliance Content</code>), bộ lọc an toàn AI kiểm tra các dấu hiệu ngôn từ kích động, bạo lực, lừa đảo hoặc vi phạm tiêu chuẩn cộng đồng và đưa các nội dung nghi vấn vào <strong><code>Content Moderation Queue (3.10.4)</code></strong>.</li><li>Tại <code>/admin/moderation</code>, <code>Admin</code> xem nội dung bị gắn cờ, ngữ cảnh bài viết và quyết định: <ul><li><strong>Chấp thuận (<code>Approve</code>)</strong>: Gỡ cờ cảnh báo để bài viết tiếp tục quy trình bình thường.</li><li><strong>Từ chối / Gỡ bỏ (<code>Reject</code>)</strong> kèm cập nhật trạng thái vi phạm của người dùng (<strong><code>3.10.5 Update User Violation Status</code></strong>): Tăng mức cảnh cáo (<code>Warning</code> → <code>Restricted</code> → <code>Suspended</code>/<code>Banned</code>).</li></ul></li></ul></li></ol><h3 id="_2-2-quan-tri-goi-cuoc-dich-vu-3-10-6-–-3-10-9" tabindex="-1">2.2. Quản trị Gói Cước Dịch vụ (<code>3.10.6</code> – <code>3.10.9</code>) <a class="header-anchor" href="#_2-2-quan-tri-goi-cuoc-dich-vu-3-10-6-–-3-10-9" aria-label="Permalink to &quot;2.2. Quản trị Gói Cước Dịch vụ (`3.10.6` – `3.10.9`)&quot;">​</a></h3><ul><li>Tại <code>/admin/subscriptions</code>, <code>Admin</code> quản lý danh mục các gói cước (<code>Basic</code>, <code>Plus</code>, <code>Enterprise</code>).</li><li><strong>Quy tắc bảo toàn thuê bao đang hoạt động</strong>: <ul><li>Khi <code>Admin</code> cập nhật giá hoặc định mức của gói (<code>3.10.8</code>), các <code>Agency</code> đang trong chu kỳ đã thanh toán vẫn giữ nguyên quyền lợi đã cấp (<code>BillingPeriodBenefits</code>); cấu hình mới áp dụng cho các đơn nâng cấp/gia hạn tiếp theo.</li><li>Khi <code>Admin</code> xóa gói (<code>3.10.9</code>), nếu gói đang có <code>Agency</code> đăng ký hoạt động thì chỉ chuyển gói sang trạng thái ngừng bán mới (<code>isActive = false</code>) thay vì xóa vật lý để bảo toàn khóa ngoại lịch sử hóa đơn.</li></ul></li></ul><h3 id="_2-3-quan-tri-bang-gia-ai-credit-3-10-10-–-3-10-12" tabindex="-1">2.3. Quản trị Bảng giá AI Credit (<code>3.10.10</code> – <code>3.10.12</code>) <a class="header-anchor" href="#_2-3-quan-tri-bang-gia-ai-credit-3-10-10-–-3-10-12" aria-label="Permalink to &quot;2.3. Quản trị Bảng giá AI Credit (`3.10.10` – `3.10.12`)&quot;">​</a></h3><ul><li>Tại <code>/admin/credit-pricing</code>, <code>Admin</code> kiểm soát chi phí credit cho <strong>4 nhóm tác vụ tính phí duy nhất</strong>: <ol><li><code>CONTENT_GENERATE</code></li><li><code>AMBASSADOR_GENERATE</code></li><li><code>COMMERCIAL_IMAGE</code></li><li><code>VIDEO_GENERATE</code></li></ol></li><li>Các tác vụ miễn phí cố định (<code>CAPTION_VARIANTS</code>, <code>HASHTAG_GENERATE</code>, <code>CHARACTER_SHEET</code>) luôn giữ <code>unit_credits = 0</code>.</li><li>Hỗ trợ cập nhật trực tiếp từng dòng (<code>3.10.11</code>) hoặc tải lên tệp CSV bảng giá (<code>3.10.12</code>) với kiểm tra hợp lệ toàn phần trước khi lưu.</li></ul><h3 id="_2-4-bang-đieu-khien-doanh-thu-sepay-xuat-bao-cao-pdf-giam-sat-he-thong-3-10-13-3-10-14-3-7-13" tabindex="-1">2.4. Bảng điều khiển Doanh thu SePay, Xuất Báo cáo PDF &amp; Giám sát Hệ thống (<code>3.10.13</code>, <code>3.10.14</code>, <code>3.7.13</code>) <a class="header-anchor" href="#_2-4-bang-đieu-khien-doanh-thu-sepay-xuat-bao-cao-pdf-giam-sat-he-thong-3-10-13-3-10-14-3-7-13" aria-label="Permalink to &quot;2.4. Bảng điều khiển Doanh thu SePay, Xuất Báo cáo PDF &amp; Giám sát Hệ thống (`3.10.13`, `3.10.14`, `3.7.13`)&quot;">​</a></h3><ul><li><strong>Doanh thu &amp; Hóa đơn (<code>3.10.13</code> &amp; <code>3.10.14</code>)</strong>: <ul><li>Tại <code>/admin/revenue</code> và <code>/admin/invoices</code>, <code>Admin</code> theo dõi biểu đồ doanh thu thực thu từ cổng <strong>SePay / PayOS (VietQR)</strong> theo ngày/tháng/quý, xem chi tiết từng hóa đơn và bấm <strong>Xuất báo cáo PDF (<code>3.10.14</code>)</strong>.</li></ul></li><li><strong>Quản lý Đường ống Thu thập Xu hướng &amp; Sức khỏe Hệ thống (<code>3.7.13</code> &amp; <code>/admin/crawler</code>, <code>/admin/health</code>)</strong>: <ul><li>Cấu hình nguồn thu thập xu hướng đa nền tảng, đặt lịch cron (<code>3.7.13</code>), kích hoạt chạy đường ống xu hướng ngay lập tức (<code>Run Pipeline Now</code>) và giám sát trạng thái các dịch vụ (<code>business-service</code>, <code>ai-service</code>, <code>publisher-service</code>, PostgreSQL, MongoDB, Redis, Neo4j, RabbitMQ).</li></ul></li></ul>',15)])])}const m=e(c,[["render",i]]);export{u as __pageData,m as default};
